import{_ as i,a0 as r,w as C,s as d,I as a,x as s,a1 as p,A as l,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const O=JSON.parse('{"title":"通过写“猜数字”游戏学习 Fortran | LCTT x X-CMD","titleTemplate":false,"description":"通过写“猜数字”游戏学习 Fortran | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通过写“猜数字”游戏学习 Fortran | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过写“猜数字”游戏学习 Fortran | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20210104 Learn Fortran by writing a -guess the number- game","title":"通过写“猜数字”游戏学习 Fortran","tag":"202110","desc":""},"relativePath":"202110/20210104 Learn Fortran by writing a -guess the number- game.md","filePath":"[post].md"}'),u={name:"202110/20210104 Learn Fortran by writing a -guess the number- game.md"};function T(E,n,g,N,f,m){const e=r("Link"),t=r("rb");return C(),d("div",null,[n[32]||(n[32]=a("h1",{id:"通过写-猜数字-游戏学习-fortran",tabindex:"-1"},[s("通过写“猜数字”游戏学习 Fortran "),a("a",{class:"header-anchor",href:"#通过写-猜数字-游戏学习-fortran","aria-label":"Permalink to “通过写“猜数字”游戏学习 Fortran”"},"​")],-1)),n[33]||(n[33]=a("blockquote",null,[a("p",null,"Fortran 是在打孔卡时代编写的语言，因此它的语法非常有限。但你仍然可以用它编写有用和有趣的程序。")],-1)),n[34]||(n[34]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202110/04/125311k6uwzpybabayyoag.jpg",alt:""})],-1)),a("p",null,[n[1]||(n[1]=s("Fortran 77 是我学习的第一门编译型编程语言。一开始时，我自学了如何在 Apple II 上用 BASIC 编写程序，后来又学会在 DOS 上用 QBasic 编写程序。但是当我去大学攻读物理学时，我又学习了 ",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Fortran"},{default:l(()=>[...n[0]||(n[0]=[s("Fortran",-1)])]),_:1}),n[2]||(n[2]=s("。",-1))]),n[35]||(n[35]=o(`<p>Fortran 曾经在科学计算中很常见。曾几何时，所有计算机系统都有一个 Fortran 编译器。Fortran 曾经像今天的 Python 一样无处不在。因此，如果你是像我这样的物理学专业学生，在 1990 年代工作，那你肯定学习了 Fortran。</p><p>我一直认为 Fortran 与 BASIC 有点相似，所以每当我需要编写一个简短程序，来分析实验室数据或执行其他一些数值分析时，我都会很快想到 Fortran。我在空闲时用 Fortran 编写了一个“猜数字”游戏，其中计算机会在 1 到 100 之间选择一个数字，并让我猜这个数字。程序会一直循环，直到我猜对了为止。</p><p>“猜数字”程序练习了编程语言中的几个概念：如何为变量赋值、如何编写语句以及如何执行条件判断和循环。这是学习新编程语言时一个很好的的实践案例。</p><h3 id="fortran-编程基础" tabindex="-1">Fortran 编程基础 <a class="header-anchor" href="#fortran-编程基础" aria-label="Permalink to “Fortran 编程基础”">​</a></h3><p>虽然 Fortran 这些年来一直在更新，但我最熟悉的还是 Fortran 77，这是我多年前学习的实现版本。Fortran 是程序员还在打孔卡上编程的年代创建的，因此“经典” Fortran 仅限于处理可以放在打孔卡上的数据。这意味着你只能编写符合以下限制条件的经典 Fortran 程序（LCTT 译注：后来的 Fortran 95 等版本已经对这些限制做了很大的改进，如有兴趣<strong>建议直接学习新版</strong>）：</p><ul><li>每张卡只允许一行源代码。</li><li>仅识别第 1-72 列（最后八列，73-80，保留给卡片分类器）。</li><li>行号（“标签”）位于第 1-5 列。</li><li>程序语句在第 7-72 列。</li><li>要表示跨行，请在第 6 列中输入一个连续字符（通常是 <code>+</code>）。</li><li>要创建注释行，请在第 1 列中输入 <code>C</code> 或 <code>*</code>。</li><li>只有字符 <code>A</code> 到<code>Z</code>（大写字母）、<code>0</code> 到<code>9</code>（数字）和特殊字符 <code>= + - * / ( ) , . $ &#39; :</code> 和空格能够使用。</li></ul><p>虽然有这些限制，你仍然可以编写非常有用和有趣的程序。</p><h3 id="在-fortran-中猜数字" tabindex="-1">在 Fortran 中猜数字 <a class="header-anchor" href="#在-fortran-中猜数字" aria-label="Permalink to “在 Fortran 中猜数字”">​</a></h3><p>通过编写“猜数字”游戏来探索 Fortran。这是我的实现代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC</span></span>
<span class="line"><span>C     PROGRAM TO GUESS A NUMBER 1-100</span></span>
<span class="line"><span>CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC</span></span>
<span class="line"><span>      PROGRAM GUESSNUM</span></span>
<span class="line"><span>      INTEGER SEED, NUMBER, GUESS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      PRINT *, &#39;ENTER A RANDOM NUMBER SEED&#39;</span></span>
<span class="line"><span>      READ *, SEED</span></span>
<span class="line"><span>      CALL SRAND(SEED)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      NUMBER = INT( RAND(0) * 100 + 1 )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      PRINT *, &#39;GUESS A NUMBER BETWEEN 1 AND 100&#39;</span></span>
<span class="line"><span> 10   READ *, GUESS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      IF (GUESS.LT.NUMBER) THEN</span></span>
<span class="line"><span>         PRINT *, &#39;TOO LOW&#39;</span></span>
<span class="line"><span>      ELSE IF (GUESS.GT.NUMBER) THEN</span></span>
<span class="line"><span>         PRINT *, &#39;TOO HIGH&#39;</span></span>
<span class="line"><span>      ENDIF</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      IF (GUESS.NE.NUMBER) GOTO 10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      PRINT *, &#39;THATS RIGHT!&#39;</span></span>
<span class="line"><span>      END</span></span></code></pre></div>`,10)),a("p",null,[n[5]||(n[5]=s("如果你熟悉其他编程语言，你大概可以通过阅读源代码来弄清楚这个程序在做什么。前三行是注释块，表示程序的功能。第四行 ",-1)),n[6]||(n[6]=a("code",null,"PROGRAM GUESSNUM",-1)),n[7]||(n[7]=s(" 将其标识为一个 ",-1)),a("ruby",null,[p(t,null,{default:l(()=>[...n[3]||(n[3]=[s("程序",-1)])]),_:1}),n[4]||(n[4]=a("rt",null,"program",-1))]),n[8]||(n[8]=s("，并由最后一行的 ",-1)),n[9]||(n[9]=a("code",null,"END",-1)),n[10]||(n[10]=s(" 语句关闭。",-1))]),a("p",null,[n[13]||(n[13]=s("定义变量后，程序会提示用户输入随机数种子。Fortran 程序无法从操作系统初始化随机数生成器，因此你必须始终使用“种子”值和 ",-1)),n[14]||(n[14]=a("code",null,"SRAND",-1)),n[15]||(n[15]=s()),a("ruby",null,[p(t,null,{default:l(()=>[...n[11]||(n[11]=[s("子程序",-1)])]),_:1}),n[12]||(n[12]=a("rt",null,"subroutine",-1))]),n[16]||(n[16]=s(" 启动随机数生成器。",-1))]),n[36]||(n[36]=o(`<p>Fortran 使用 <code>RAND(0)</code> 函数生成 0 到 0.999…… 之间的随机数。参数 <code>0</code> 告诉 <code>RAND</code> 函数生成一个随机数。将此随机数乘以 100 以生成 0 到 99.999…… 之间的数字，然后加 1 得到 1 到 100.999…… 之间的值。<code>INT</code> 函数将结果截断为整数；因此，变量 <code>NUMBER</code> 就是一个介于 1 到 100 之间的随机数。</p><p>程序会给出提示，然后进入一个循环。Fortran 不支持更现代的编程语言中可用的 <code>while</code> 或 <code>do-while</code> 循环（LCTT 译注：Fortran 95 等新版支持，也因此在一定程度上减少了 <code>GOTO</code> 的使用）。相反，你必须使用标签（行号）和 <code>GOTO</code> 语句来构建自己的循环。这就是 <code>READ</code> 语句有一个行号的原因：你可以在循环末尾使用 <code>GOTO</code> 跳转到此标签。</p><p>穿孔卡片没有 <code>&lt;</code>（小于）和 <code>&gt;</code>（大于）符号，因此 Fortran 采用了另一种语法来进行值比较。要测试一个值是否小于另一个值，请使用 <code>.LT.</code>（小于）。要测试一个值是否大于另一个值，请使用 <code>.GT.</code>（大于）。等于和不等于分别是 <code>.EQ.</code> 和 <code>.NE.</code>。</p><p>在每次循环中，程序都会验证用户的猜测值。如果用户的猜测值小于随机数，程序打印 <code>TOO LOW</code>，如果猜测大于随机数，程序打印 <code>TOO HIGH</code>。循环会一直持续，直到用户的猜测值等于目标随机数为止。</p><p>当循环退出时，程序打印 <code>THATS RIGHT!</code> 并立即结束运行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gfortran -Wall -o guess guess.f</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ./guess</span></span>
<span class="line"><span> ENTER A RANDOM NUMBER SEED</span></span>
<span class="line"><span>93759</span></span>
<span class="line"><span> GUESS A NUMBER BETWEEN 1 AND 100</span></span>
<span class="line"><span>50</span></span>
<span class="line"><span> TOO LOW</span></span>
<span class="line"><span>80</span></span>
<span class="line"><span> TOO HIGH</span></span>
<span class="line"><span>60</span></span>
<span class="line"><span> TOO LOW</span></span>
<span class="line"><span>70</span></span>
<span class="line"><span> TOO LOW</span></span>
<span class="line"><span>75</span></span>
<span class="line"><span> TOO HIGH</span></span>
<span class="line"><span>73</span></span>
<span class="line"><span> TOO LOW</span></span>
<span class="line"><span>74</span></span>
<span class="line"><span> THATS RIGHT!</span></span></code></pre></div><p>每次运行程序时，用户都需要输入不同的随机数种子。如果你总是输入相同的种子，程序给出的随机数也会一直不变。</p><h3 id="在其他语言中尝试" tabindex="-1">在其他语言中尝试 <a class="header-anchor" href="#在其他语言中尝试" aria-label="Permalink to “在其他语言中尝试”">​</a></h3><p>在学习一门新的编程语言时，这个“猜数字”游戏是一个很好的入门程序，因为它以非常简单的方式练习了几个常见的编程概念。通过用不同的编程语言实现这个简单的游戏，你可以弄清一些核心概念以及比较每种语言的细节。</p><p>你有最喜欢的编程语言吗？如何用你最喜欢的语言来编写“猜数字”游戏？跟随本系列文章来查看你可能感兴趣的其他编程语言示例吧。</p><hr>`,11)),a("p",null,[n[18]||(n[18]=s("via: ",-1)),p(e,{href:"https://opensource.com/article/21/1/fortran"},{default:l(()=>[...n[17]||(n[17]=[s("https://opensource.com/article/21/1/fortran",-1)])]),_:1})]),a("p",null,[n[23]||(n[23]=s("作者：",-1)),p(e,{href:"https://opensource.com/users/jim-hall"},{default:l(()=>[...n[19]||(n[19]=[s("Jim Hall",-1)])]),_:1}),n[24]||(n[24]=s(" 选题：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...n[20]||(n[20]=[s("lujun9972",-1)])]),_:1}),n[25]||(n[25]=s(" 译者：",-1)),p(e,{href:"https://github.com/unigeorge"},{default:l(()=>[...n[21]||(n[21]=[s("unigeorge",-1)])]),_:1}),n[26]||(n[26]=s(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:l(()=>[...n[22]||(n[22]=[s("wxy",-1)])]),_:1})]),a("p",null,[n[29]||(n[29]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...n[27]||(n[27]=[s("LCTT",-1)])]),_:1}),n[30]||(n[30]=s(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:l(()=>[...n[28]||(n[28]=[s("Linux中国",-1)])]),_:1}),n[31]||(n[31]=s(" 荣誉推出",-1))])])}const S=i(u,[["render",T]]);export{O as __pageData,S as default};
